287	function parse_candidate_signals(string $loop): array
288	{
289	    $section = markdown_section($loop, 'Final Distillation');
290	    $classifications = [];
291	    $total = 0;
292	
293	    if (
294	        $section === null
295	        || ! preg_match('/^- Candidate signals:\s*\R(.*?)(?=^- [A-Z].*?:|\z)/ms', $section, $matches)
296	    ) {
297	        return [
298	            'total' => 0,
299	            'classifications' => [],
300	        ];
301	    }
302	
303	    foreach (preg_split('/\R/', trim($matches[1])) ?: [] as $line) {
304	        if (! preg_match('/^\s*-\s*(.+)$/', $line, $signal)) {
305	            continue;
306	        }
307	
308	        $value = trim($signal[1]);
309	
310	        if ($value === '' || strcasecmp($value, 'none') === 0) {
311	            continue;
312	        }
313	
314	        $total++;
315	
316	        if (preg_match('/\s->\s([a-z-]+)\s->\s/i', $value, $classification) !== 1) {
317	            $classifications['unknown'] = ($classifications['unknown'] ?? 0) + 1;
318	
319	            continue;
320	        }
321	
322	        $key = strtolower($classification[1]);
323	        $classifications[$key] = ($classifications[$key] ?? 0) + 1;
324	    }
325	
326	    ksort($classifications);
327	
328	    return [
329	        'total' => $total,
330	        'classifications' => $classifications,
331	    ];
