334	function blockers_present(string $loop): bool
335	{
336	    $section = markdown_section($loop, 'Blockers');
337	
338	    if ($section === null) {
339	        return false;
340	    }
341	
342	    $entries = [];
343	
344	    foreach (preg_split('/\R/', $section) ?: [] as $line) {
345	        if (trim($line) === '') {
346	            continue;
347	        }
348	
349	        if (preg_match('/^-[ \t]*(.+)$/', $line, $matches)) {
350	            $entries[] = $matches[1];
351	
352	            continue;
353	        }
354	
355	        if ($entries === []) {
356	            $entries[] = trim($line);
357	
358	            continue;
359	        }
360	
361	        $lastEntry = array_key_last($entries);
362	        $entries[$lastEntry] .= ' '.trim($line);
363	    }
364	
365	    foreach ($entries as $entry) {
366	        $text = strtolower(normalize_whitespace($entry));
367	        $text = rtrim($text, '.,;:!?');
368	
369	        if (
370	            $text === 'none'
371	            || $text === 'none currently'
372	            || $text === 'no blocker currently'
373	            || preg_match('/^no blockers?$/', $text) === 1
374	            || preg_match('/^no blocker for solo todo #\d+$/', $text) === 1
375	            || preg_match(
376	                '/^no active (?:correctness|implementation(?: or verification)?) blocker remains(?:\. the earlier blocker is resolved)?$/',
377	                $text,
378	            ) === 1
379	            || preg_match('/^the (?:previous analyzer evidence|earlier) blocker is resolved$/', $text) === 1
380	        ) {
381	            continue;
382	        }
383	
384	        return true;
385	    }
386	
387	    return false;
388	}
