573	        return 'unknown';
574	    }
575	
576	    $normalized = normalize_whitespace(rtrim($value, '.,;:!?'));
577	
578	    if (preg_match(
579	        '/^`?(complete \+ loop improvement|complete|blocked)`?(?=$|[ \t]+-[ \t]+)/i',
580	        $normalized,
581	        $matches,
