589	function normalize_analyzer_verdict(string $value, string $provenance): string
590	{
591	    $value = trim($value);
592	
593	    if ($value === '' || str_contains($value, '<')) {
594	        return 'unknown';
595	    }
596	
597	    $verdictCandidate = $value;
598	
599	    if (preg_match('/^`?Verdict:\s*/i', $verdictCandidate, $matches) === 1) {
600	        $verdictCandidate = substr($verdictCandidate, strlen($matches[0]));
601	    }
602	
603	    if (preg_match(
604	        '/^`?(not used|not applicable|skipped|deferred)`?(?=$|[.,;:!?]|[ \t]+(?:-[ \t]+|because\b|for\b))/i',
605	        $verdictCandidate,
606	        $matches,
607	    )) {
608	        return strtolower($matches[1]) === 'deferred' ? 'deferred' : 'not used';
609	    }
610	
611	    if (preg_match('/^`?(yes|no)(?:`|[.,;:!?])*\s*$/i', $verdictCandidate, $matches)) {
612	        return strtolower($matches[1]);
613	    }
614	
615	    if (
616	        $provenance === 'explicit-verdict-row'
617	        && preg_match('/^`?(yes|no)`?(?=[ \t]*(?:;|-[ \t]+))/i', $verdictCandidate, $matches) === 1
618	    ) {
619	        return strtolower($matches[1]);
620	    }
621	
622	    if (preg_match(
623	        '/^`?(proper|flawed|blocked-by-missing-evidence|blocked by missing evidence)`?(?=$|[.,;:!?]|[ \t]+(?:-[ \t]+|because\b|for\b))/i',
624	        $verdictCandidate,
625	        $matches,
626	    )) {
627	        $normalizedVerdict = strtolower($matches[1]);
628	
629	        if ($normalizedVerdict === 'blocked by missing evidence') {
630	            $normalizedVerdict = 'blocked-by-missing-evidence';
631	        }
632	
633	        return $normalizedVerdict;
634	    }
635	
636	    return normalize_value($value);
637	}
